use float4::F4E2M1;
use std::{fmt::Write, fs, path::Path};

fn main() -> std::io::Result<()> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let output = root.join("src/bit/lut.rs");

    let mut file = String::new();

    file.push_str(
        "//! Generated FP4 E2M1 lookup tables.\n\
                //!\n\
                //! Generated from `float4::F4E2M1`.\n\
                //! DO NOT EDIT THIS FILE BY HAND.\n\
                //!\n\
                //! F4 Indexing: `(c << 8) | (a << 4) | b`.\n\n",
    );

    file.push_str(&gen_f4_lut3(
        "LUT_F4",
        |a, b, c| a.mul_add(b, c),
        HiF4 {
            c0: |a, b| a + b,
            c1: |a, b| a * b,
            c2: |a, b| a - b,
            c3: |a, b| a / b,
            c4: |a, b| a.div_euclid(b),
            c5: |a, b| a % b,
            c6: |a, b| a.log(b),
            c7: |a, b| a.atan2(b),
            c8: |a, b| a.powf(b),
            c9: |a, b| a.hypot(b),
            c10: |a, b| a.midpoint(b),
            c11: |a, b| a.rem_euclid(b),
            c12: |a, b| match F4E2M1::from_f64(b).to_bits() {
                0 => a.cos(),
                1 => a.sin(),
                2 => a.acos(),
                3 => a.asin(),
                4 => a.acosh(),
                5 => a.asinh(),
                6 => a.ln(),
                7 => a.ln_1p(),
                8 => a.log2(),
                9 => a.log10(),
                10 => a.tan(),
                11 => a.tanh(),
                12 => a.atan(),
                13 => a.atanh(),
                14 => a.exp(),
                15 => a.exp2(),
                _ => unreachable!(),
            },
            c13: |a, b| match F4E2M1::from_f64(b).to_bits() {
                0 => a.exp_m1(),
                1 => a.sqrt(),
                2 => a.cbrt(),
                3 => a.recip(),
                4 => a.floor(),
                5 => a.ceil(),
                6 => a.trunc(),
                7 => a.to_degrees(),
                8 => a.to_radians(),
                9 => a.fract(),
                _ => 0.0,
            },
        },
    ));

    fs::write(output, file)
}

#[expect(dead_code)]
fn gen_f6_lut2(
    name: &str,
    op_lo: impl Fn(f64, f64) -> f64,
    op_hi: impl Fn(f64, f64) -> f64,
) -> String {
    let mut out = String::new();

    writeln!(out, "#[rustfmt::skip]").unwrap();
    writeln!(out, "pub static {name}: [u8; 256] = [").unwrap();

    for a in 0..16 {
        for b in 0..16 {
            let af = F4E2M1::from_bits(a).to_f64();
            let bf = F4E2M1::from_bits(b).to_f64();

            let lo = F4E2M1::from_f64(op_lo(af, bf)).to_bits();
            let hi = F4E2M1::from_f64(op_hi(af, bf)).to_bits();

            let result = (hi << 4) | lo;

            writeln!(out, "    0x{:X}, // (0x{a:X}, 0x{b:X})", result).unwrap();
        }
    }

    writeln!(out, "];").unwrap();

    out
}

struct HiF4<
    C0: Fn(f64, f64) -> f64,
    C1: Fn(f64, f64) -> f64,
    C2: Fn(f64, f64) -> f64,
    C3: Fn(f64, f64) -> f64,
    C4: Fn(f64, f64) -> f64,
    C5: Fn(f64, f64) -> f64,
    C6: Fn(f64, f64) -> f64,
    C7: Fn(f64, f64) -> f64,
    C8: Fn(f64, f64) -> f64,
    C9: Fn(f64, f64) -> f64,
    C10: Fn(f64, f64) -> f64,
    C11: Fn(f64, f64) -> f64,
    C12: Fn(f64, f64) -> f64,
    C13: Fn(f64, f64) -> f64,
> {
    c0: C0,
    c1: C1,
    c2: C2,
    c3: C3,
    c4: C4,
    c5: C5,
    c6: C6,
    c7: C7,
    c8: C8,
    c9: C9,
    c10: C10,
    c11: C11,
    c12: C12,
    c13: C13,
}

fn gen_f4_lut3<
    C0: Fn(f64, f64) -> f64,
    C1: Fn(f64, f64) -> f64,
    C2: Fn(f64, f64) -> f64,
    C3: Fn(f64, f64) -> f64,
    C4: Fn(f64, f64) -> f64,
    C5: Fn(f64, f64) -> f64,
    C6: Fn(f64, f64) -> f64,
    C7: Fn(f64, f64) -> f64,
    C8: Fn(f64, f64) -> f64,
    C9: Fn(f64, f64) -> f64,
    C10: Fn(f64, f64) -> f64,
    C11: Fn(f64, f64) -> f64,
    C12: Fn(f64, f64) -> f64,
    C13: Fn(f64, f64) -> f64,
>(
    name: &str,
    op: impl Fn(f64, f64, f64) -> f64,
    interleaved: HiF4<C0, C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, C13>,
) -> String {
    let mut out = String::new();

    writeln!(out, "#[cfg(feature = \"lut-f4\")]").unwrap();
    writeln!(out, "#[rustfmt::skip]").unwrap();
    writeln!(out, "pub static {name}: [u8; 4096] = [").unwrap();

    for c in 0..16 {
        for a in 0..16 {
            for b in 0..16 {
                let af = F4E2M1::from_bits(a).to_f64();
                let bf = F4E2M1::from_bits(b).to_f64();
                let cf = F4E2M1::from_bits(c).to_f64();

                let lo = F4E2M1::from_f64(op(af, bf, cf)).to_bits();
                let hi = F4E2M1::from_f64(match c {
                    0 => (interleaved.c0)(af, bf),
                    1 => (interleaved.c1)(af, bf),
                    2 => (interleaved.c2)(af, bf),
                    3 => (interleaved.c3)(af, bf),
                    4 => (interleaved.c4)(af, bf),
                    5 => (interleaved.c5)(af, bf),
                    6 => (interleaved.c6)(af, bf),
                    7 => (interleaved.c7)(af, bf),
                    8 => (interleaved.c8)(af, bf),
                    9 => (interleaved.c9)(af, bf),
                    10 => (interleaved.c10)(af, bf),
                    11 => (interleaved.c11)(af, bf),
                    12 => (interleaved.c12)(af, bf),
                    13 => (interleaved.c13)(af, bf),
                    _ => 0.0,
                })
                .to_bits();

                let result = (hi << 4) | lo;

                writeln!(out, "    0x{:X}, // (0x{a:X}, 0x{b:X}, 0x{c:X})", result,).unwrap();
            }
        }
    }

    writeln!(out, "];").unwrap();

    out
}
